def unary(z):
    d={}
    for p in [-2,-1,-0.5,0.5,1,1.5,2,3]:
        d[f'^{p}']=z**p
    for k in [-1,1]:
        d[f'exp({k}z)']=np.exp(k*z)
    d['sin']=np.sin(z); d['cos']=np.cos(z); d['log']=np.log(z); d['tanh']=np.tanh(z)
    d['z e^-z']=z*np.exp(-z); d['sin(2z)']=np.sin(2*z); d['cos(2z)']=np.cos(2*z)
